fn read_skybox(current: Res<CurrentSkybox>, images: Res<Assets<Image>>) {
    let Some(id) = current.0 else { return };
    if let Some(img) = images.get(id) {
        // 0.19+: `pixel_bytes` returns `Result<_, TextureAccessError>`, was `Option`.
